import { test, expect } from '@playwright/test';

test.describe('Save Card Details for Future Purchases', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/payment');
  });

  test('should successfully save card details and display confirmation message', async ({ page }) => {
    // Intercept the API call to mock a successful response
    await page.route('**/api/payment/save-card', (route) => {
      route.continue();
    });

    // Fill in card number using getByLabel
    const cardNumberInput = page.getByLabel('Card Number');
    await cardNumberInput.fill('4120111101110001');

    // Fill in expiry date using getByLabel
    const expiryDateInput = page.getByLabel('Expiry Date');
    await expiryDateInput.fill('12/25');

    // Fill in CVV using getByLabel
    const cvvInput = page.getByLabel('CVV');
    await cvvInput.fill('123');

    // Click the save button using getByRole
    const saveButton = page.getByRole('button', { name: /save card/i });
    await saveButton.click();

    // Wait for the API response
    await page.waitForResponse(response =>
      response.url().includes('/api/payment/save-card') && response.status() === 200
    );

    // Verify success message appears
    const successMessage = page.getByText('Card saved successfully');
    await expect(successMessage).toBeVisible();

    // Verify card details are displayed in saved cards section
    const savedCardDisplay = page.getByText('Visa ending in 1111');
    await expect(savedCardDisplay).toBeVisible();

    // Verify confirmation modal is visible
    const confirmationModal = page.locator('[data-testid="confirmation-modal"]');
    await expect(confirmationModal).toBeVisible();
  });

  test('should display error message when saving card with invalid details', async ({ page }) => {
    // Intercept the API call to mock a validation error
    await page.route('**/api/payment/save-card', (route) => {
      route.abort('failed');
    });

    // Fill in card number using getByLabel
    const cardNumberInput = page.getByLabel('Card Number');
    await cardNumberInput.fill('123');

    // Fill in expiry date using getByLabel
    const expiryDateInput = page.getByLabel('Expiry Date');
    await expiryDateInput.fill('12/25');

    // Fill in CVV using getByLabel
    const cvvInput = page.getByLabel('CVV');
    await cvvInput.fill('123');

    // Click the save button using getByRole
    const saveButton = page.getByRole('button', { name: /save card/i });
    await saveButton.click();

    // Wait for the error response
    await page.waitForResponse(response =>
      response.url().includes('/api/payment/save-card') && response.status() === 400
    );

    // Verify error message appears
    const errorMessage = page.getByText('Invalid card details');
    await expect(errorMessage).toBeVisible();

    // Verify error styling is applied
    const errorContainer = page.locator('[data-testid="error-container"]');
    await expect(errorContainer).toHaveClass(/error-message/);

    // Verify card details are not saved
    const savedCardDisplay = page.getByText('Visa ending in 1111');
    await expect(savedCardDisplay).not.toBeVisible();

    // Verify save button is still enabled for retry
    await expect(saveButton).toBeEnabled();
  });
});
